# Build the assembled test output using the inferred connector translations.
H=W=26
grid=[[0]*W for _ in range(H)]
objects={
 5: ([(1,8)] + [(2,c) for c in range(8,15)] + [(3,8)] + [(4,c) for c in range(8,15)] + [(5,8)], [(2,15),(4,15),(5,10),(5,13)]),
 8: ([(2,c) for c in range(19,24)] + [(3,19),(3,23),(4,19),(4,23),(5,19),(6,19),(6,20)], [(1,19),(1,23),(5,23),(6,21)]),
 9: ([(11,2),(11,3),(11,6),(11,7),(12,2),(12,7),(13,2),(13,7)] + [(14,c) for c in range(2,8)], [(10,3),(10,6)]),
 4: ([(r,c) for r in range(13,16) for c in range(13,16)], [(12,14),(13,12),(15,16),(16,13)]),
 6: ([(19,c) for c in range(3,8)] + [(20,3),(20,7),(21,3),(21,7)], [(22,3),(22,7)]),
 1: ([(20,22),(21,19),(21,22),(22,19),(22,22),(23,19),(23,22)] + [(24,c) for c in range(19,23)], [(19,22),(20,19),(22,18),(24,18),(25,22)])
}
shift={5:(16,-3),8:(7,-9),9:(11,4),4:(0,0),6:(-14,7),1:(-4,-6)}
from collections import defaultdict
occ=defaultdict(list)
for col,(cells,dots) in objects.items():
 dr,dc=shift[col]
 for r,c in cells: occ[r+dr,c+dc].append(col)
 for r,c in dots: occ[r+dr,c+dc].append(2)
outs=[]
for (r,c),cs in occ.items():
 if not (0<=r<H and 0<=c<W): print('outbounds',r,c,cs)
 if len([x for x in cs if x!=2])>1: print('color collision',r,c,cs)
 v=next((x for x in cs if x!=2),2)
 if v==2 and len(cs)>1: v=2
 grid[r][c]=v
print('colors', {k:sum(x==k for row in grid for x in row) for k in range(1,10)})
print('marker positions',sorted((r,c) for (r,c),cs in occ.items() if 2 in cs))
print('\n'.join(' '.join(map(str,row)) for row in grid))
